import * as moment from 'moment';
import { Directive, forwardRef, Input } from '@angular/core';
import { NG_VALIDATORS, Validator, ValidationErrors, AbstractControl, ValidatorFn } from '@angular/forms';

export const dateValidtorFn = (dateFormat: string): ValidatorFn => {
  return (c: AbstractControl): { [key: string]: any } => {
    const val = c.value;
    if (!val) {
      return null;
    }
    const isDate = moment(val, dateFormat, true).isValid();
    return isDate ? null : { date: true };
  };
};

const DATE_VALIDATOR: any = {
  provide: NG_VALIDATORS,
  useExisting: forwardRef(() => DateValidator),
  multi: true,
};

@Directive({
  selector: '[date][formControlName],[date][formControl],[date][ngModel]',
  providers: [DATE_VALIDATOR],
})
export class DateValidator implements Validator, OnInit {
  @Input() date: string;
  private validator: ValidatorFn;
  ngOnInit() {
    this.validator = dateValidtorFn(this.date || 'MM/DD/YYYY');
  }
  validate(c: AbstractControl): ValidationErrors {
    return this.validator(c);
  }
}

import { NgModule, OnInit } from '@angular/core';
@NgModule({
  declarations: [DateValidator],
  exports: [DateValidator],
})
export class DateValidatorModule {}
